    mdm: NotRequired[pulumi.Input[Optional['SettingMistNacMdmArgsDict']]]
    """
    Mobile Device Management CoA settings for Mist NAC
    """
    server_cert: NotRequired[pulumi.Input[Optional['SettingMistNacServerCertArgsDict']]]
    """
    RADIUS server certificate presented by Mist NAC during EAP-TLS
    """
    use_ip_version: NotRequired[pulumi.Input[Optional[_builtins.str]]]
    """
    IP version used by NAS devices and Mist Edge proxies to reach Mist NAC
    """
    use_ssl_port: NotRequired[pulumi.Input[Optional[_builtins.bool]]]
    """
    By default, NAS devices (switches/aps) and proxies(mxedge) are configured to use port TCP2083(RadSec) to reach mist-nac. Set `use_ssl_port`==`true` to override that port with TCP43 (ssl), This is an org level setting that is applicable to wlans, switch_templates, and mxedge_clusters that have mist-nac enabled
    """
    usermac_expiry: NotRequired[pulumi.Input[Optional[_builtins.int]]]
    """
    Allow customer to configure an expiry time for usermacs by attaching an `inactive_endpoint` label to those which have been inactive for the configured period of time (in days). 0 means no expiry
    """

